    /*--------  1.0 Global style  -------*/
        
        .form-checkbox + .form-label {
            font-weight: 400;
            color: stencilColor('color-textBase');
            &:before {
                border-radius: 3px;
            }
        }

        .form-field {
            margin-bottom: 20px;
        }

        a[data-test="forgot-password-link"] {
            display: block;
            margin-top: 10px;
        }

        .alertBox-message {
            strong, b {
                line-height: inherit;
                display: inline-block;
                vertical-align: middle;
            }
        }

        .layout {
            padding: 60px 0px;
            .layout-main {
                width: 60%;
                padding: 0 30px 0 0;
                .checkout-steps {
                    padding-right: 0;
                }
            }
            .layout-cart {
                width: 40%;
                padding: 0;
            }
        }

        .checkout-steps {
            > .checkout-step {
                padding: 0px;
                margin-bottom: 25px;
                border: none;
                + .checkout-step {
                    padding-top: 25px;
                    border-top: 1px solid #eeeeee;
                }
                &[checkout-step="customer"],
                &[checkout-step="shipping"],
                &[checkout-step="billing"] {
                    .optimizedCheckout-buttonPrimary {
                        min-width: 180px;
                    }
                }
            }
        }

        .stepHeader {
            padding: 0;
            flex-wrap: wrap;
            position: relative;
            .stepHeader-figure {
                width: 100%;
                display: block;
                height: auto;
                margin-right: 0;
                .stepHeader-counter {
                    width: 45px;
                    height: 45px;
                    border-radius: 50%;
                    color: #ffffff;
                    font-size: 20px;
                    font-weight: 400;
                    line-height: 42px;
                    position: relative;
                    margin-right: 15px;
                    display: inline-block;
                    vertical-align: middle;
                    background-color: #383e47;
                    -webkit-transform: scale(1);
                    transform: scale(1);
                    &.stepHeader-counter--complete {
                       transform: scale(1); 
                    }
                }
                .stepHeader-title {
                    margin: 0;
                    padding: 0;
                    font-size: 24px;
                    min-width: 350px;
                    display: inline-block;
                    vertical-align: middle;
                    text-transform: uppercase;
                }
            }
            .stepHeader-body {
                margin-top: 20px;
                margin-left: 65px;
                .checkout-address--static .address-entry {
                    margin-bottom: 5px;
                }
            }
            .stepHeader-actions {
                position: absolute;
                right: 0;
                top: 8px;
                margin: 0;
                z-index: 10;
            }
            .stepHeader-counter--complete svg {
                padding: 10px;
            }
        }

        .checkout-view-content {
            margin-top: 20px;
            .checkout-form {
                margin-top: 0;
                margin-right: 0;
                margin-bottom: 0;
                max-width: none;
                @media (min-width: 1025px) {
                    margin-left: 65px;
                }
                .form-body {
                    p > a,
                    a[data-test="forgot-password-link"] {
                        color: #005599;
                        font-weight: 500;
                    }
                }
            }
            .form-legend {
                width: auto;
                font-size: 16px;
                font-weight: 700;
                line-height: 24px;
                padding-bottom: 0px;
                margin-bottom: 20px;
                position: relative;
                display: inline-block;
                text-transform: uppercase;
                color: #b20000;
                font-weight: 700;
                font-family: "Rajdhani", Arial, Helvetica, sans-serif;
                + a[data-test="shipping-mode-toggle"] {
                    top: -6px;
                    position: relative;
                }
            }
            .form-body {
                margin-bottom: 0;
            }
        }

        #checkout-shipping-comments {
            .optimizedCheckout-form-input {
                min-height: 75px;
            }
        }

        #checkout-payment-continue {
            font-size: 16px;
            color: #ffffff;
            border-color: #b20000;
            background-color: #b20000;
            padding: 17px 30px 16px 30px;
        }

        .form-checklist-body {
            .form-checklist-container {
                padding-top: 0;
                padding-bottom: 10px;
                p {
                    margin-bottom: 0;
                }
            }
        }
        #checkout-shipping-options {
            margin-bottom: 20px;
        }

        .orderConfirmation {
            padding-top: 0;
            h1[data-test="order-confirmation-heading"] {
                margin-bottom: 30px;
            }
            #createAccountButton {
                min-width: 200px;
            }
        }

        .socialBadges-header {
            margin-top: 1.5rem;
        }

        .customerEmail-action {
            margin-top: 28px;
        }

    /*--------  RESPONSIVE  -------------*/
        @media (max-width: 1024px) {
            .layout,
            .optimizedCheckout-header {
                padding-left: 15px;
                padding-right: 15px;
            }
        }
        @media (max-width: 992px) {
            .layout {
                .layout-main {
                    padding: 0;
                    width: 100%;
                }
                .layout-cart {
                    padding: 0;
                    width: 100%;
                }
            }

            .stepHeader {
                .stepHeader-figure {
                    .stepHeader-counter {
                        width: 35px;
                        height: 35px;
                        line-height: 35px;
                        margin-right: 10px;
                        font-size: 16px;
                        &:before {
                            font-size: 16px;
                        }
                    }
                    .stepHeader-title {
                        font-size: 20px;
                    }
                }
                .stepHeader-actions {
                    top: 0px;
                    .optimizedCheckout-buttonSecondary {
                        text-transform: uppercase;
                        min-width: 0;
                        padding-left: 10px;
                        padding-right: 10px;
                        padding-top: 5px;
                        padding-bottom: 5px;
                    }
                }
                .stepHeader-body {
                    margin-top: 10px;
                    margin-left: 55px;
                }
            }

            .checkout-view-content {
                margin-top: 10px;
            }

            .checkout-steps {
                > .checkout-step {
                    margin-bottom: 25px;
                    + .checkout-step {
                        padding-top: 25px;
                    }
                }
            }

            .customerView-actions {
                .optimizedCheckout-buttonSecondary {
                    text-transform: uppercase;
                    min-width: 0;
                    padding-left: 10px;
                    padding-right: 10px;
                    padding-top: 5px;
                    padding-bottom: 5px;
                }
            }
        }

        @media (max-width: 767px) {
            .optimizedCheckout-header {
                .checkoutHeader-link img {
                    max-height: 30px;
                }
                .checkoutHeader-content {
                    padding: 20px 0;
                }
                .checkoutHeader-heading {
                    text-align: left;
                    font-size: 30px;
                    line-height: 1;
                }
            }
            .stepHeader .stepHeader-body,
            .checkout-view-content .checkout-form {
                margin-left: 0;
            }
            .layout {
                padding-bottom: 90px;
            }
            #checkout-shipping-comments .optimizedCheckout-form-input {
                min-height: 0;
            }

            .orderConfirmation {
                h1[data-test="order-confirmation-heading"] {
                    font-size: 26px;
                    margin-bottom: 20px;
                }
                .form-body {
                    margin-bottom: 0;
                }
            }
        }

        @media (max-width: 550px) {
            .customerEmail-body {
                width: 100%;
            }
            .customerEmail-action {
                width: 100%;
                padding-left: 0;
                margin-top: 0;
            }
            .optimizedCheckout-orderSummary {
                margin-left: 15px;
                margin-right: 15px;
                margin-bottom: 15px;
                margin-top: 30px;
                width: calc(100% - 30px);
                .cart-section .product {
                    .product-figure {
                        width: 75px;
                        padding-right: 15px;
                    }
                    .product-body {
                        width: calc(75% - 75px);
                    }
                    .product-actions {
                        align-self: flex-start;
                        -ms-flex-order: 3;
                        order: 3;
                        text-align: right;
                        width: 25%;
                    }
                }
            }
            #checkout-payment-continue {
                padding: 11px 15px 10px 15px;
            }
            .cart-modal-body {
                padding-left: 0;
